update qt_page_deployment
commit_sha = #{commitSha}, status = #{status}, release_id = #{releaseId}, previous_release_id = #{previousReleaseId}, attempt_count = #{attemptCount}, next_attempt_time = #{nextAttemptTime}, error_code = #{errorCode}, error_message = #{errorMessage}, log_text = #{logText}, file_count = #{fileCount}, total_bytes = #{totalBytes}, release_available = #{releaseAvailable}, finished_time = #{finishedTime},
where deployment_id = #{deploymentId}

update qt_page_deployment
set status = 'SUPERSEDED', finished_time = now()
where site_id = #{siteId}
  and request_version < #{requestVersion}
  and status in ('PENDING', 'RESOLVING', 'DOWNLOADING', 'VALIDATING')
